import React from "react";


export interface LogoIJRProps extends Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, "color"> {
  /** Altura do logo em px. Default: 56. */
  height?: number;
  /** Cor do "Insper" (e do monograma "Jr." inicial). Default: currentColor — herda do contexto. */
  color?: string;
  /** Cor do "Jr." (estado final). Default: #f5333f. */
  redColor?: string;
  /** Duração total da animação em ms. Default: 900. */
  duration?: number;
}

const WORDMARK_URL =
  "data:image/png;base64,";
const MONOGRAM_URL =
  "data:image/png;base64,";

// Wordmark intrinsic ratio (full "Insper Jr.").
const WORD_RATIO = 3.85;
// Where "Jr." begins inside the wordmark, as a fraction of width.
const JR_START = 0.7460;

export const LogoIJR: React.FC<LogoIJRProps> = ({
  href = "/",
  height = 56,
  color,
  redColor = "#f5333f",
  duration = 900,
  style,
  ...rest
}) => {
  const expanded = height * WORD_RATIO;
  const collapsed = expanded * (1 - JR_START);

  const cssVars: React.CSSProperties = {
    "--ijr-h": `${height}px`,
    "--ijr-red": redColor,
    "--ijr-dur": `${duration}ms`,
    "--ijr-w-expanded": `${expanded}px`,
    "--ijr-w-collapsed": `${collapsed}px`,
    ...(color ? { color } : {}),
  } as React.CSSProperties;

  return (
    <>
      <style>{LOGO_CSS}</style>
      <a
        {...rest}
        href={href}
        className={`ijr-logo${rest.className ? " " + rest.className : ""}`}
        aria-label="Insper Jr."
        style={{ ...cssVars, ...style }}
      >
        <span className="ijr-logo__word" aria-hidden="true" />
        <span className="ijr-logo__mono" aria-hidden="true" />
      </a>
    </>
  );
};

export default LogoIJR;

/* ------------------------------------------------------------------ */
/* Scoped CSS. Injected once per render — React deduplicates identical
   <style> blocks so this is fine even with multiple instances. */
/* ------------------------------------------------------------------ */

const LOGO_CSS = `
.ijr-logo {
  --ijr-ease: cubic-bezier(.2, .7, .2, 1);
  display: inline-flex;
  align-items: center;
  position: relative;
  height: var(--ijr-h);
  width: var(--ijr-w-collapsed);
  overflow: hidden;
  text-decoration: none;
  color: inherit;
  cursor: pointer;
  transition: width calc(var(--ijr-dur) * 0.6) var(--ijr-ease);
}
.ijr-logo:hover,
.ijr-logo:focus-visible {
  width: var(--ijr-w-expanded);
  outline: none;
}

.ijr-logo__word,
.ijr-logo__mono {
  position: absolute;
  top: 0;
  right: 0;
  height: 100%;
  pointer-events: none;
}
.ijr-logo__word { width: var(--ijr-w-expanded); }
.ijr-logo__mono { width: calc(var(--ijr-w-expanded) * ${1 - JR_START}); }

.ijr-logo__word::before,
.ijr-logo__word::after {
  content: "";
  position: absolute;
  inset: 0;
  -webkit-mask-image: url("${WORDMARK_URL}");
          mask-image: url("${WORDMARK_URL}");
  -webkit-mask-size: 100% 100%;
          mask-size: 100% 100%;
  -webkit-mask-repeat: no-repeat;
          mask-repeat: no-repeat;
  -webkit-mask-position: center;
          mask-position: center;
}
.ijr-logo__word::before {
  background: currentColor;
  clip-path: inset(0 ${((1 - JR_START) * 100).toFixed(2)}% 0 0);
}
.ijr-logo__word::after {
  background: var(--ijr-red);
  clip-path: inset(0 0 0 ${(JR_START * 100).toFixed(2)}%);
}

.ijr-logo__mono {
  background: currentColor;
  -webkit-mask-image: url("${MONOGRAM_URL}");
          mask-image: url("${MONOGRAM_URL}");
  -webkit-mask-size: 100% 100%;
          mask-size: 100% 100%;
  -webkit-mask-repeat: no-repeat;
          mask-repeat: no-repeat;
  -webkit-mask-position: center;
          mask-position: center;
  transition: opacity calc(var(--ijr-dur) * 0.4) var(--ijr-ease) calc(var(--ijr-dur) * 0.55);
}
.ijr-logo:hover .ijr-logo__mono,
.ijr-logo:focus-visible .ijr-logo__mono { opacity: 0; }

.ijr-logo__word {
  opacity: 0;
  transition: opacity calc(var(--ijr-dur) * 0.4) var(--ijr-ease) calc(var(--ijr-dur) * 0.55);
}
.ijr-logo:hover .ijr-logo__word,
.ijr-logo:focus-visible .ijr-logo__word { opacity: 1; }

@media (prefers-reduced-motion: reduce) {
  .ijr-logo,
  .ijr-logo__word,
  .ijr-logo__mono { transition-duration: 1ms !important; }
}
`;
